 1 | <?php
 2 | /**
 3 |  * Bento Grid Block Snippet
 4 |  * @var \Kirby\Cms\Block $block
 5 |  */
 6 | $layout = $block->layout_type()->value();
 7 | $theme = $block->theme()->value();
 8 | 
 9 | // Map layout types to Tailwind CSS grid classes (for outer container)
10 | $gridClass = match($layout) {
11 |     'hero_split' => 'grid-cols-1 md:grid-cols-2 lg:grid-cols-3',
12 |     'quadrant' => 'grid-cols-1 md:grid-cols-2 lg:grid-cols-2',
13 |     'feature_showcase' => 'grid-cols-1 md:grid-cols-3 lg:grid-cols-4',
14 |     default => 'grid-cols-1 md:grid-cols-3 lg:grid-cols-4'
15 | };
16 | 
17 | // Map themes to Tailwind classes
18 | $themeContainerClass = match($theme) {
19 |     'oceanic' => 'bg-oceanic-dark dark text-white',
20 |     'accent' => 'bg-oceanic-accent dark text-white',
21 |     'dark' => 'bg-ink dark text-white',
22 |     'slate' => 'bg-slate-teal dark text-white',
23 |     'liberty' => 'bg-liberty-blue dark text-white',
24 |     'heritage' => 'bg-heritage-red dark text-white',
25 |     'gold' => 'bg-warm-gold text-ink',
26 |     'frost' => 'bg-frost-mint text-ink',
27 |     default => 'bg-canvas text-ink'
28 | };
29 | 
30 | $themeCellClass = match($theme) {
31 |     'oceanic', 'accent', 'dark', 'slate', 'liberty', 'heritage' => 'bg-white/5 shadow-xl',
32 |     'gold', 'frost', 'light', '' => 'bg-white shadow-sm',
33 |     default => 'bg-white shadow-sm'
34 | };
35 | 
36 | // Fixed gap strategy per FLUID-GLASS-BENTO-SCHEMA.md
37 | // Instead of margins or variable gaps, we enforce a strict --grid-gap.
38 | ?>
39 | <style>
40 | .bento-container[data-bento-grid] {
41 |     --grid-gap: 2rem;
42 |     --bento-radius: 1.5rem;
43 |     display: grid;
44 |     gap: var(--grid-gap);
45 |     padding: var(--grid-gap);
46 |     grid-auto-rows: minmax(120px, auto);
47 | }
48 | .bento-item {
49 |     border-radius: var(--bento-radius);
50 |     overflow: hidden;
51 | }
52 | </style>
53 | 
54 | <section class="bento-container w-full transition-colors duration-500 <?= $themeContainerClass ?> <?= $gridClass ?> grid-flow-dense" data-bento-grid>
55 |     <?php foreach ($block->items()->toBlocks() as $index => $item): ?>
56 |         <?php 
57 |             $colSpanClass = 'col-span-1';
58 |             $rowSpanClass = 'row-span-1'; 
59 | 
60 |             // True staggered masonry layout
61 |             $pattern = $index % 7;
62 |             
63 |             if ($pattern === 0) {
64 |                 $colSpanClass = 'md:col-span-2 lg:col-span-2';
65 |                 $rowSpanClass = 'md:row-span-3 lg:row-span-3'; // Large, wide
66 |             } elseif ($pattern === 1) {
67 |                 $colSpanClass = 'md:col-span-1 lg:col-span-1';
68 |                 $rowSpanClass = 'md:row-span-2 lg:row-span-2'; // Tall
69 |             } elseif ($pattern === 2) {
70 |                 $colSpanClass = 'md:col-span-1 lg:col-span-1';
