72 |             } elseif ($pattern === 3) {
73 |                 $colSpanClass = 'md:col-span-1 lg:col-span-1';
74 |                 $rowSpanClass = 'md:row-span-2 lg:row-span-2'; // Tall
75 |             } elseif ($pattern === 4) {
76 |                 $colSpanClass = 'md:col-span-2 lg:col-span-2';
77 |                 $rowSpanClass = 'md:row-span-2 lg:row-span-2'; // Wide
78 |             } elseif ($pattern === 5) {
79 |                 $colSpanClass = 'md:col-span-1 lg:col-span-1';
80 |                 $rowSpanClass = 'md:row-span-3 lg:row-span-3'; // Very tall
81 |             } elseif ($pattern === 6) {
